const msg = $input.first().json;

if (msg.event?.event && msg.event.event !== 'post') return [];

if (msg.messages?.[0]?.from_me === true)  return [];

const phone = msg.messages?.[0]?.from;
const msgObj = msg.messages?.[0];

if (!phone || !msgObj) return [];

let text = '';
let messageType = msgObj.type;
let imageId = null;
let audioId = null;

if (msgObj.type === 'text') {
  text = msgObj.text?.body || '';
} else if (msgObj.type === 'audio' || msgObj.type === 'voice') {
  text = '[AUDIO recibido - pendiente transcripción]';
  audioId = msgObj.audio?.id || msgObj.voice?.id || null;
} else if (msgObj.type === 'image') {
  text = '[IMAGEN recibida - caption: ' + (msgObj.image?.caption || 'sin caption') + ']';
  imageId = msgObj.image?.id || null;
} else if (msgObj.type === 'document') {
  text = '[DOCUMENTO recibido: ' + (msgObj.document?.fileName || 'sin nombre') + ']';
} else {
  text = '[Mensaje de tipo ' + msgObj.type + ']';
}

return [{ json: { phone, text, messageType, imageId, audioId } }];

const orig = $input.first().json;
const fileName = orig.phone + '-' + Date.now() + '.jpg';
return [{ json: { ...orig, fileName } }];

const orig = $('Normalizar payload').item.json;
const fileInfo = $('Preparar nombre de archivo').item.json;
const uploadResult = $input.first().json;
const downloadItem = $('Descargar imagen (Whapi)').item;
const downloadBinary = downloadItem && downloadItem.binary && downloadItem.binary.data;

let text = orig.text;

const statusCode = uploadResult && uploadResult.statusCode;
const uploadFailed = !uploadResult || uploadResult.error || (statusCode && statusCode >= 300);
const notAnImage = !downloadBinary || !downloadBinary.mimeType || downloadBinary.mimeType.indexOf('image/') !== 0;
const failed = uploadFailed || notAnImage;

if (!failed) {
  const imageUrl = 'https://ntiyvjqdhjfqqxdgjlsx.supabase.co/storage/v1/object/public/chat-images/' + fileInfo.fileName;
  text = text + ' [IMAGEN:' + imageUrl + ']';
}

return [{ json: { phone: orig.phone, text, messageType: orig.messageType } }];

const row = $json;

const botActive = row?.bot_active !== undefined ? row.bot_active : true;
const vendedor = row?.vendedor || null;
const etiqueta = row?.etiqueta || null;
const vendedorId = row?.vendedor_id || null;
const cotizacionPendiente = row?.cotizacion_pendiente || null;
const menuMostradoAt = row?.menu_mostrado_at || null;

return [{ json: { phone: row.phone, text: row.text, messageType: row.messageType, bot_active: botActive, vendedor, etiqueta, vendedor_id: vendedorId, cotizacion_pendiente: cotizacionPendiente, menu_mostrado_at: menuMostradoAt } }];

const item = $input.first().json;
const texto = (item.text || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase();

const palabrasHorario = ['horario','horarios','abierta','abierto','abiertas','abiertos','cerrada','cerrado','cerradas','cerrados','abre','abren','atiende','atienden','atencion'];
const palabrasContacto = ['telefono','tel','numero','num','celu','cel','whatsapp','wsp','wpp','contacto','direccion','ubicacion','donde queda','como llego','donde estan'];
const nombresSucursal = ['cordoba','cba','tucuman','tuc','salta','portal shopping','peatonal mendoza'];

const matchHorario = palabrasHorario.some(p => texto.includes(p));
const matchContacto = palabrasContacto.some(p => texto.includes(p));
const matchSucursal = nombresSucursal.some(p => texto.includes(p));
const consultarSucursal = matchHorario || matchContacto || matchSucursal;

let sucursalesCsv;

if (consultarSucursal) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://docs.google.com/spreadsheets/d/1knDtcf4pVlT3NWyq6sVFCRH8p2N_LX9ZgNXweMMKB6g/export?format=csv&gid=0'
    });
    sucursalesCsv = typeof response === 'string' ? response : JSON.stringify(response);
  } catch (error) {
    sucursalesCsv = undefined;
  }
}

return [{ json: { ...item, sucursales_csv: sucursalesCsv } }];

