const item = $input.first();

// Renombrar de .oga a .ogg que sí acepta Groq
item.binary.audio.fileName = 'audio.ogg';
item.binary.audio.fileExtension = 'ogg';
item.binary.audio.mimeType = 'audio/ogg';

return [item];

const item = $input.first().json;
const text = (item.text || '').trim();
const textNorm = text.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

const TZ = 'America/Argentina/Tucuman';
const ahora = DateTime.now().setZone(TZ);
const hoy = ahora.toFormat('yyyy-MM-dd');

let estado = {};
try {
  const raw = item.cotizacion_pendiente;
  estado = raw ? (typeof raw === 'string' ? JSON.parse(raw) : raw) : {};
} catch (e) { estado = {}; }

const menuMostradoAt = item.menu_mostrado_at ? DateTime.fromISO(item.menu_mostrado_at).setZone(TZ) : null;
const esNuevoDia = !menuMostradoAt || menuMostradoAt.toFormat('yyyy-MM-dd') !== hoy;
const pidioMenu = textNorm === 'menu' || textNorm === 'menu?' || textNorm === 'ver menu';

const clienteYaAsignado = !!item.vendedor_id;

function salida(accion_idx, extra) {
  const nuevo_estado = (extra && extra.nuevo_estado) || estado;
  return [{ json: { ...item, ...(extra || {}), accion_idx, nuevo_estado, marcar_menu_mostrado: accion_idx === 0 } }];
}

if (esNuevoDia || pidioMenu) {
  return salida(0, { nuevo_estado: { modo: 'menu_mostrado' } });
}

const modo = estado.modo || 'menu_mostrado';

if (modo === 'esperando_tipo_cliente') {
  const esEmpresa = /empresa|mayorista|revendedor/.test(textNorm);
  const tipo_cliente = esEmpresa ? 'empresa' : 'minorista';
  return salida(2, { nuevo_estado: { modo: 'esperando_nombre', motivo: estado.motivo, tipo_cliente } });
}

if (modo === 'esperando_nombre') {
  const categoria_destino = estado.tipo_cliente === 'empresa' ? 'mayorista_revendedor' : 'minorista';
  return salida(3, {
    nuevo_estado: { modo: 'libre' },
    categoria_destino,
    motivo: estado.motivo,
    nombre_cliente_derivacion: text,
  });
}

if (modo === 'libre') {
  return salida(4, { nuevo_estado: estado });
}

const opcion = (textNorm.match(/^([1-6])/) || [])[1];

if (opcion === '1' || opcion === '2') {
  return salida(4, { nuevo_estado: { modo: 'libre' } });
}
if (opcion === '3' || opcion === '4') {
  const motivo = opcion === '3' ? 'presupuesto' : 'pedido_pendiente';
  if (clienteYaAsignado) {
    return salida(3, { nuevo_estado: { modo: 'libre' }, categoria_destino: 'minorista', motivo, nombre_cliente_derivacion: null });
  }
  return salida(1, { nuevo_estado: { modo: 'esperando_tipo_cliente', motivo } });
}
if (opcion === '5') {
  return salida(3, { nuevo_estado: { modo: 'libre' }, categoria_destino: 'minorista', motivo: 'generico', nombre_cliente_derivacion: null });
}
if (opcion === '6') {
  return salida(3, { nuevo_estado: { modo: 'libre' }, categoria_destino: 'proveedores', motivo: 'proveedor', nombre_cliente_derivacion: null });
}

return salida(5, { nuevo_estado: estado });

const resp = $input.first().json;
const ctx = $('Router de menu').item.json;

let output;
if (!resp || resp.ok === undefined) {
  output = 'Tuvimos un problema tecnico al procesar tu consulta. Proba escribir de nuevo en unos minutos.';
} else if (resp.derivar === false) {
  output = resp.mensaje_cliente || 'En este momento no tenemos vendedores disponibles. Te vamos a contactar a la brevedad.';
} else if (resp.fuera_horario) {
  output = 'Anote tu consulta — ' + (resp.vendedor_nombre || 'nuestro equipo') + ' te va a contactar ' + (resp.proximo_texto || 'apenas se conecte') + '. Mientras tanto, seguimos charlando por aca si queres avanzar con algo mas.';
} else {
  output = '¡Listo! ' + (resp.vendedor_nombre || 'Un vendedor de nuestro equipo') + ' te va a contactar en breve.';
}

return [{ json: { ...ctx, output, derivacion_resultado: resp } }];

const orig = $('Normalizar payload').item.json;
const groqResult = $input.first().json;

let text;
if (groqResult && typeof groqResult.text === 'string' && groqResult.text.trim().length > 0) {
  text = groqResult.text.trim();
} else {
  text = 'No pude entender el audio que enviaste. ¿Podés escribirlo o volver a enviarlo?';
}

return [{ json: { phone: orig.phone, text, messageType: orig.messageType, imageId: orig.imageId ?? null } }];
